(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0029.js"] = [{"id":"glyph-seal-8d76","script":"seal","character":"赶","reading":"gǎn","description":"追赶,从后面追上\n急赴\n驱逐\n⒈追你追我～。迎头～上。～超世界先进水平。〈引〉加快，从速，及时达到～快。～紧。～工。～上这班车。\n⒉驱使，驾驭，驱逐～马儿。～牛车。把外籍罪犯～出国门。\n赶qián 1.兽类翘尾奔跑。 2.引申为翘起尾巴或屁股。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-赶"},{"id":"glyph-seal-8d77","script":"seal","character":"起","reading":"qǐ","description":"qǐ：(1)由躺而坐或由坐而立等～床。～立。～居。～夜。\n(2)离开原来的位置～身。～运。～跑。\n(3)开始～始。～码（最低限度，最低的）。～步。～初。～讫。～源。\n(4)拔出，取出～锚。～获。\n(5)领取（凭证）～护照。\n(6)由下向上，由小往大里涨～伏。～劲。～色。\n(7)发生，产生，发动，提出～风。～腻。～敬。～疑。～义。～诉。\n(8)长出～痱子。\n(9)拟定～草。\n(10)建造，建立～房子。白手～家。\n(11)群，组，批一～（一块儿）。\n(12)量词，指件，宗一～案件。\n(13)自，从～小儿就淘气。\n(14)用在动词后，表示动作的趋向想～。掀～。兴（xīng）～。\n(15)用在动词后，与来”连用，表示动作开始唱～来。\n(16)用在动词后，常与不”或得”连用，表示胜任；亦表示达到某一种标准看不～。经得～检验。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-起"},{"id":"glyph-seal-8d81","script":"seal","character":"趁","reading":"chèn","description":"chèn：(1)利用时间、机会～早。～机。～势。～火打劫（趁人家发生火灾时去抢劫，喻在别人危难时乘机去捞好处）。～热打铁。\n(2)搭乘～车。～船。\n(3)逐，追赶花底山蜂远～人”。\n(4)往，赴～墟（赶集）。～熟（逃荒到丰收之处）。\n(5)富有～钱。～几身衣服。\n(6)古同称”，适合。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趁"},{"id":"glyph-seal-8d84","script":"seal","character":"趄","reading":"jū；qiè；jv","description":"qiè：倾斜～坡。～着身子。\n〔趔～〕见趔”。\njū：〔趑～〕见趑”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趄"},{"id":"glyph-seal-8d85","script":"seal","character":"超","reading":"chāo","description":"chāo：(1)越过，高出～越。高～。～出。～额。～龄。～等。～载。～重。～支。\n(2)跳上，跨过挟泰山以～北海”。\n(3)在一定范围以外～自然。～音速。～导现象。\n(4)遥远～遥。～忽。\n(5)怅惘的样子武侯～然不对”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-超"},{"id":"glyph-seal-8d8a","script":"seal","character":"越","reading":"yuè","description":"yuè：(1)度过，超出～过。～冬。～级。～轨。～权。～境。～位。～狱。～俎代庖。\n(2)声音、情感扬起，昂扬激～。声音清～。\n(3)表示程度加深～发（更加）。～加。～快～好。\n(4)消散精神劳则～”。\n(5)失坠，坠落陨～。射其左。～于车下”。\n(6)中国古民族名百～（亦作百粤”）。\n(7)中国周代诸侯国名◇用作浙江省东部的别称～剧。～凫楚乙（乙”，燕子。喻对于同一事物，由于自身条件的局限而作出不同的判断）。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-越"},{"id":"glyph-seal-8d8b","script":"seal","character":"趋","reading":"qū","description":"步,行走\n⒈快走～走。～而迎之。\n⒉向往，奔向，向着某方面发展～向。～势。～之若鹜。～于一致。\n⒊〈古〉通\"促\"。催促。\n趋cù 1.敦促;促使。 2.催迫;催促。 3.急促;迫切。 4.赶快;立即。 5.矮，短促。\n趋qù 1.志向;意趣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趋"},{"id":"glyph-seal-8d91","script":"seal","character":"趑","reading":"zī","description":"zī：〔～趄（jū）〕ａ．行走困难；ｂ．想前进又不敢前进，如～～不前”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趑"},{"id":"glyph-seal-8da3","script":"seal","character":"趣","reading":"qù；cù","description":"qù：(1)趋向志～。意～。旨～。\n(2)兴味，使人感到愉快兴～。乐～。情～。雅～。妙～。相映成～。～事。～味。\ncù：古同促”，催促；急促。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趣"},{"id":"glyph-seal-8db3","script":"seal","character":"足","reading":"zú","description":"zú：(1)脚～下（对对方的敬称）。～迹。～球。～坛。失～。高～（敬辞，称别人的学生）。举～轻重。画蛇添～。\n(2)器物下部的支撑部分鼎～。碗～。\n(3)充分，够量～月。～见。～智多谋。\n(4)完全～以。～色。\n(5)值得，够得上不～为凭。微不～道。\n(6)增益以昼～夜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-足"},{"id":"glyph-seal-8dbf","script":"seal","character":"趿","reading":"tā","description":"tā：〔～拉〕穿鞋只套上脚尖（拉”读轻声）。\n〔～拉儿（lɑr）〕拖鞋，只能套着脚尖没有后帮的鞋。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-趿"},{"id":"glyph-seal-8dc3","script":"seal","character":"跃","reading":"yuè","description":"若将跃舞。\n上竖;上举\n⒈跳跳～。飞～。\n①跳着前进。\n②飞快地前进。\n跃tì 1.见\"跃跃\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跃"},{"id":"glyph-seal-8dc4","script":"seal","character":"跄","reading":"qiāng","description":"天子穆穆,诸侯皇皇,\n跄qiāng 1.行走有节奏貌。 2.起舞。 3.以头撞。参见\"跄地\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跄"},{"id":"glyph-seal-8dcb","script":"seal","character":"跋","reading":"bá","description":"bá：(1)翻山越岭～涉。\n(2)踩，践踏～前踬后（喻进退两难）。\n(3)文章或书籍正文后面的短文，说明写作经过、资料来源等与成书有关的情况～文。～语。序～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跋"},{"id":"glyph-seal-8dcc","script":"seal","character":"跌","reading":"diē","description":"diē：(1)摔～跤。～倒。\n(2)下降，低落～落。～销。水位下～。\n(3)顿足，跺～足大叹。\n(4)疾行～蹄而行千里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跌"},{"id":"glyph-seal-8dce","script":"seal","character":"跎","reading":"tuó","description":"tuó：〔蹉～〕见蹉”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跎"},{"id":"glyph-seal-8dd6","script":"seal","character":"跖","reading":"zhí","description":"zhí：同蹠”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跖"},{"id":"glyph-seal-8ddb","script":"seal","character":"跛","reading":"bǒ","description":"bǒ：腿或脚有病，走路时身体不平衡，瘸～脚。～子。～行。～鳖千里（喻本身条件再差，只要不懈努力，终能获得成功）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跛"},{"id":"glyph-seal-8ddd","script":"seal","character":"距","reading":"jù；jv","description":"jù：(1)相隔的空间和时间相～数里。～离。行（háng）～。株～。差（chā）～。\n(2)雄鸡爪子后面突出像脚趾的部分。\n(3)古同拒”，抵抗。\n(4)古同巨”，大。\n(5)古同讵”，岂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-距"},{"id":"glyph-seal-8ddf","script":"seal","character":"跟","reading":"gēn","description":"gēn：(1)脚的后部，踵脚后～。\n(2)鞋袜的后部高～鞋。袜后～儿。\n(3)随在后面，紧接着～随。～踪。\n(4)赶，及～不上班。\n(5)和，同我～他在一起工作。\n(6)对，向我已经～他说了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跟"},{"id":"glyph-seal-8de3","script":"seal","character":"跣","reading":"xiǎn","description":"xiǎn：光着脚，不穿鞋袜～足。～跗（露出脚背）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跣"},{"id":"glyph-seal-8de8","script":"seal","character":"跨","reading":"kuà","description":"kuà：(1)抬腿向前或向旁移动越过，迈过～进。～入。～度。\n(2)骑，两脚分在器物的两边坐着或立着～马。小孩～着门槛。\n(3)超过时间或地区之间的界限～越。～年度。～国公司。\n(4)附在旁边～院。\n(5)古同胯”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跨"},{"id":"glyph-seal-8dea","script":"seal","character":"跪","reading":"guì","description":"guì：(1)两膝着地，腰和股都伸直～拜。～叩。\n(2)足蟹六～而二螯”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跪"},{"id":"glyph-seal-8def","script":"seal","character":"路","reading":"lù","description":"lù：(1)道，往来通行的地方道～。公～。水～。陆～。～途。～程。～人（行路的人，喻不相干的人）。狭～相逢。\n(2)思想或行动的方向、途径思～。生～。出～。～子。～数（shù）。\n(3)方面，地区外～货。各～人马。\n(4)种类一～货色。\n(5)大，正厥声载～”。～门（宫室最内的正门）。～车（古代帝王及诸侯贵族所乘的车）。～舆（古代君主所乘的车）。～寝（古代君主处理政事的宫室）。\n(6)车筚～。乘～。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-路"},{"id":"glyph-seal-8df3","script":"seal","character":"跳","reading":"tiào；táo","description":"tiào：(1)两脚离地全身向上或向前的动作～跃。～水。～荡。～踧。～高。～远。～舞。弹（tán）～。暴～如雷。～梁小丑（指上蹿下跳，兴风作浪的微不足道的坏人）。\n(2)越过～班。～棋。～槽。\n(3)一起一伏地动心～。眼～。心惊肉～。\ntáo：古同逃”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跳"},{"id":"glyph-seal-8df5","script":"seal","character":"践","reading":"jiàn","description":"履行;实现\n⒈踩，踏～踏。马～。\n⒉实行，履行～言。～约。实～。\n⒊到，临重～故里。\n⒋〈古〉通\"翦\"。灭掉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-践"},{"id":"glyph-seal-8dfb","script":"seal","character":"跻","reading":"jī","description":"达到\n晋升\n下坠","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-跻"},{"id":"glyph-seal-8e0a","script":"seal","character":"踊","reading":"yǒng","description":"登,登上\n百姓疲于土木之功,金\n⒈跳跃。\n⒉登上，上涨腾～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踊"},{"id":"glyph-seal-8e0f","script":"seal","character":"踏","reading":"tà","description":"tà：(1)用脚踩～步。～板。～青（春天到郊外散步。亦称踏春”）。～雪。～月。践～。糟～。脚～实地。\n(2)亲自到现场去～看。～勘。～查。～访。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踏"},{"id":"glyph-seal-8e12","script":"seal","character":"踒","reading":"wō","description":"脚或腿扭伤。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-8e14","script":"seal","character":"踔","reading":"chuō","description":"chuō：(1)跳，跳跃～厉（喻精神振奋，如～～风发”）。\n(2)超越～远（遥远）。～绝（高超）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踔"},{"id":"glyph-seal-8e1d","script":"seal","character":"踝","reading":"huái","description":"huái：〔～骨〕脚腕两旁凸起的部分。亦称踝子骨”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踝"},{"id":"glyph-seal-8e1e","script":"seal","character":"踞","reading":"jù；jv","description":"jù：(1)蹲，坐龙蹯虎～（形容地势险要）。～坐。箕～（古人席地而坐把两腿像八字形分开）。\n(2)占据～守。盘～（亦作盘据”）。雄～一方。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踞"},{"id":"glyph-seal-8e2c","script":"seal","character":"踬","reading":"zhì","description":"跌倒,摔倒\n遭受挫折\n碍,阻碍\n踬于中道。╠","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踬"},{"id":"glyph-seal-8e35","script":"seal","character":"踵","reading":"zhǒng","description":"zhǒng：(1)脚后跟举～。接～而至。\n(2)走到～见（常去相见）。～谢。～门相告。\n(3)追随，继承～继。～武（跟着别人的脚印走，喻继承前人的事业或是效法前人）。～事增华（指继承前人的事业并更加发展）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踵"},{"id":"glyph-seal-8e3d","script":"seal","character":"踽","reading":"jǔ；jv","description":"jǔ：〔～～〕形容独自走路孤零零的样子，如～～独行”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-踽"},{"id":"glyph-seal-8e41","script":"seal","character":"蹁","reading":"pián","description":"pián：(1)走路脚不正的样子。\n(2)膝盖。\n〔～跹〕形容旋转舞蹈。亦作翩跹”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹁"},{"id":"glyph-seal-8e42","script":"seal","character":"蹂","reading":"róu","description":"róu：践踏～踏。～躏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹂"},{"id":"glyph-seal-8e44","script":"seal","character":"蹄","reading":"tí","description":"tí：马、牛、猪等生在趾端的保护物，亦指有角质保护物的脚～子。～筋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹄"},{"id":"glyph-seal-8e47","script":"seal","character":"蹇","reading":"jiǎn","description":"jiǎn：(1)跛，行走困难～足。～步。\n(2)迟钝，不顺利～涩。～滞。～拙。～运。时乖命～。\n(3)傲慢。\n(4)穷困。\n(5)驽马，亦指驴。\n(6)文言语助词～谁留兮中洲？\n(7)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹇"},{"id":"glyph-seal-8e48","script":"seal","character":"蹈","reading":"dǎo","description":"dǎo：(1)践踏，踩～袭（走别人走过的老路，沿用前人旧例）。～节（信守节操）。～海（跳到海里自杀）。赴汤～火。循规～矩。\n(2)跳动舞～。手舞足～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹈"},{"id":"glyph-seal-8e4a","script":"seal","character":"蹊","reading":"qī；xī","description":"xī：(1)小路谚曰桃李不言，下自成～。”～径（途径，如独辟～～”）。\n(2)践踏牵牛以～人之田而夺之牛”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹊"},{"id":"glyph-seal-8e4b","script":"seal","character":"蹋","reading":"tà","description":"tà：(1)踏舞辄数十人相随，～地为节。”\n(2)踢穿域～鞠”（鞠”，古代的一种皮球）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹋"},{"id":"glyph-seal-8e51","script":"seal","character":"蹑","reading":"niè","description":"蹑履相逢迎。\n⒉跟踪，追随追～。～踪。\n⒊动作很轻的样子，也作\"捏\"～手～脚。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹑"},{"id":"glyph-seal-8e59","script":"seal","character":"蹙","reading":"cù","description":"cù：(1)紧迫穷～。\n(2)皱，收缩～眉。～额。～皱。～缩。～金（用拈紧的金线刺绣，使刺绣的纹路绉缩起来。亦称拈金”）。\n(3)局促不安～～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹙"},{"id":"glyph-seal-8e69","script":"seal","character":"蹩","reading":"bié","description":"bié：跛，扭伤了脚腕子～脚（ａ．跛脚；ｂ．；质量不好或技艺低劣、本领不高）。～伤。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹩"},{"id":"glyph-seal-8e6c","script":"seal","character":"蹬","reading":"dēng","description":"dēng：同登”②。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹬"},{"id":"glyph-seal-8e6d","script":"seal","character":"蹭","reading":"cèng","description":"cèng：(1)磨，擦～脱一层皮。\n(2)由擦过而沾上～一身灰。\n(3)拖延磨（mó）～。～时间。\n(4)一步一步缓慢地移动慢慢往前～。\n(5)指白占便宜坐～车。\n〔～蹬（dèng）〕ａ．失势难进的样子，如或乃～～穷波，陆死盐田”；ｂ．喻失意、潦倒，如岂知～～不称意，八年梁益雕朱颜”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹭"},{"id":"glyph-seal-8e72","script":"seal","character":"蹲","reading":"dūn","description":"dūn：(1)两腿尽量弯曲，像坐的样子，但臀部不着地～下。～伏。～踞。～腿。\n(2)喻呆着或闲居～膘。～窝。～班房（坐牢）。\n〔～苗〕在一定时期内控制施肥和灌水，进行中耕和镇压，使幼苗根部下扎，生长健壮，防止多余茎叶生长。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹲"},{"id":"glyph-seal-8e74","script":"seal","character":"蹴","reading":"cù","description":"cù：(1)踢～鞠（踢球）。\n(2)踏～踏。一～而就。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹴"},{"id":"glyph-seal-8e76","script":"seal","character":"蹶","reading":"juě；jué","description":"jué：(1)跌倒。\n(2)挫折，失败一～不振。\n(3)竭尽，枯竭天下财产，何得不～？\n(4)踏，踩。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蹶"},{"id":"glyph-seal-8e81","script":"seal","character":"躁","reading":"zào","description":"zào：性急，不冷静～动。～进。～狂（浮躁轻狂）。急～。浮～。骄～。烦～。性情～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躁"},{"id":"glyph-seal-8e85","script":"seal","character":"躅","reading":"zhú","description":"zhú：足迹。\n〔踯～〕见踯”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躅"},{"id":"glyph-seal-8eab","script":"seal","character":"身","reading":"shēn","description":"shēn：(1)人、动物的躯体，物体的主要部分～躯。人～。～材。～段。船～。树～。\n(2)指人的生命或一生～世。献～。\n(3)亲自，本人自～。亲～。～教。～体力行。\n(4)统指人的地位、品德出～。～分（fèn）。～败名裂。\n(5)孕，娠～孕。\n(6)量词，指整套衣服做了一～儿新衣服。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-身"},{"id":"glyph-seal-8eac","script":"seal","character":"躬","reading":"gōng","description":"gōng：(1)身体。\n(2)自身，亲自反～自问。～行实践。事必～亲。\n(3)弯曲身体鞠～。～身下拜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躬"},{"id":"glyph-seal-8eaf","script":"seal","character":"躯","reading":"qū","description":"身孕\n躯口”的省称。宋元时代女真族和蒙古族称被俘获并强迫服劳役的汉族人为躯口”\n指生命","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-躯"},{"id":"glyph-seal-8f66","script":"seal","character":"车","reading":"chē","description":"①陆地上安设轮子的运输工具汽～、马～。\n②利用轮轴旋转的工具水～、吊～。\n③机器～床、～间。\n④用车床切削东西～圆。\n⑤用水车取水～水。\n⑥姓。又见jū。\n【车床】一种常用的金属切削机床。主要用来做内圆、外圆和螺纹加工。又叫旋床。\n【车技】一种杂技节目。表演者利用特制的单轮车、双轮车作载人运行、翻车过桌或在特制的高架上作'定车'等各种表演动作。\n【车厘子】〈港台〉樱桃。英语音译词。\n【车裂】中国古代一种残酷的死刑。将人头和四肢分别绑在五辆车上，以马架车，同时分驰，撕裂肢体。俗称五马分尸。\n【车水马龙】车像流水，马像游龙。形容车马来往不绝、繁华热闹的景象。\n【车载斗量】用车装，用斗量。形容数量非常多。多用来表示不足为奇。\n【车辙】车子经过路面时轧出的痕迹。\n⒈象旗中的一种棋子。\n⒉见chē。\n⒈有轮子的陆上交通工具马～。汽～。轿～。乘用～。火～。\n⒉利用轮轴转动的某些器具水～。纺纱～。滑轮～。〈引〉机器试～。开～。\n⒊旋床～床。\n⒋使用旋床～光。～圆。\n⒌使用水车取水～水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-车"},{"id":"glyph-seal-8f67","script":"seal","character":"轧","reading":"zhá；ga","description":"挤入;拥挤\n结交\n核查\n排挤,倾轧\n⒈〈方〉\n①挤，拥挤不要～。\n②结交～朋友。\n③核算，查对～清帐目。\n⒉见yà、zhá。\n⒈排挤，碾压倾～。～棉花。～马路。\n⒈压～辊。～钢机。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轧"},{"id":"glyph-seal-8f68","script":"seal","character":"轨","reading":"guǐ","description":"车轮的痕迹,车辙\n法则、法度\n⒈车子两轮之间的距离车同～。〈喻〉车轮的痕迹城门之～。\n⒉轨道，一定的线路五星循～而行。有～电车。特指铺设轨道的钢铁条铺铁～。架钢～。〈喻〉法度，规则，办法，秩序等纳入正～。制止越～行为。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轨"},{"id":"glyph-seal-8f69","script":"seal","character":"轩","reading":"xuān","description":"文轩之与敝舆。\n⒈〈古〉一种有帷幕的车，泛指车子乘～。\n⒉有窗槛的长廊或小屋西～。\n轩xiàn 1.大的肉片。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轩"},{"id":"glyph-seal-8f6b","script":"seal","character":"轫","reading":"rèn","description":"通仞”。古时的一种长度单位\n车轮\n柔弱;懒散\n通韧”。柔软而坚固","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轫"},{"id":"glyph-seal-8f6c","script":"seal","character":"转","reading":"zhuǎn","description":"回还,转动\n⒈旋动，改变方向、位置或情势等～动。～身。～移。～变。～败为胜。\n⒉不是直接的，中间要经过别的人或地方～告。～运。请～交。～手买卖。\n⒈旋，绕，绕着某点或某物移动旋～。打～。～圈子。车轮飞～。\n⒉量词。绕一圈叫绕\"一转\"。\n转zhuǎi 1.见\"转文\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-转"},{"id":"glyph-seal-8f6e","script":"seal","character":"轮","reading":"lún","description":"引申为车子\n凡平圆形像车轮似的东西\n未央前殿月轮\n⒈安在车上、机器上，能旋转并促使车、机器动作的东西车～子。三～车。齿～儿。偏心～。\n⒊依照次序转～流。～班。第二～。该～到你了。\n①图形或物体的外围。\n②事物的概况。\n轮lún 1.车轮。 2.指车牙。 3.指车毂。 4.代指车。 5.收卷钓线的转轮。 6.古代制作瓦瓶的圆形木模。 7.古代的一种兵器。 8.制作车轮的工匠。 9.树的横枝\n。 10.指月亮。 11.兼指太阳。 12.指人的头与四肢。 13.轮船的省称。 14.面积的纵度。 15.高大貌。 16.边缘，外围。 17.回转;转动。 18.轮流;依次更替\n。 19.瞪着眼来回看。 20.量词。辆。用以计车数。 21.量词。多用于圆形之物，如日﹑月。 22.量词。次;遍。用于循环的事物或动作。 23.挥动◇作\"抡\"。 24.","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轮"},{"id":"glyph-seal-8f70","script":"seal","character":"轰","reading":"hōng","description":"雷鸣、炮击、爆破等的隆隆声\n枪炮、雷电等对准或瞄准爆发\n猛烈攻击\n驱赶;赶开\n⒈像声词。雷鸣、炮击等发出的巨大响声～鸣。～隆。\n⒉用大炮、炸弹、导弹等破坏～击。～炸。\n⒊赶，驱逐～出去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轰"},{"id":"glyph-seal-8f72","script":"seal","character":"轲","reading":"kē","description":"专指古代孟子名\n⒈〈古〉一种车子。\n⒉见于人名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轲"},{"id":"glyph-seal-8f74","script":"seal","character":"轴","reading":"zhóu","description":"车子\n字画下端便于悬挂或卷起的圆杆\n把平面或立体分成对称部分的直线\n⒈支持轮子或其它机件的圆柱形部件，有固定的和转动的两种汽车～。飞轮～。曲～磨床。\n⒉像轴的东西～儿线。\n⒊将平面或立体分成对称部分的直线～线。\n⒋指字、画卷下面的木杆，因而借指装裱成卷的书或字画壁上挂有三～画。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轴"},{"id":"glyph-seal-8f76","script":"seal","character":"轶","reading":"yì","description":"突击\n轶yì 1.后车超前车。引申为超越。 2.突袭，突击。 3.超绝。 4.散失。 5.通\"逸\"。安闲，逸乐。 6.通\"逸\"。奔驰;逃跑。 7.通\"溢\"。\n轶dié 1.更替;轮流。 2.见\"轶荡\"。\n轶zhé 1.车迹。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轶"},{"id":"glyph-seal-8f78","script":"seal","character":"轸","reading":"zhěn","description":"伤痛～怀。～念。\n星名，二十八宿之一。\n⒈〈古〉车箱底部后面的横木车～四尺。又指车子来～。\n⒉弦乐器上转动弦线的轴。\n⒊转动～转。\n⒋悲痛，痛念，怜悯～悼。～怀。～恤。哀～。\n⒌星宿名。二十八宿之一。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轸"},{"id":"glyph-seal-8f7b","script":"seal","character":"轻","reading":"qīng","description":"轻车\n轻工业的简称\n化学元素氢的旧译\n分量不大。与重”相对\n⒈份量小，跟\"重\"相对这张桌子较～。～于鸿毛。\n⒉数量少，程度浅工作～。～伤。\n⒊用力小～放。～声。\n⒋认为无所谓，不重要～敌。～视。\n⒌随便，不庄重～易。～率。～佻。\n⒍浅薄，便当～微。～便。～舟已过万重山。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轻"},{"id":"glyph-seal-8f7c","script":"seal","character":"轼","reading":"shì","description":"轼shì〈古〉车厢前用作扶手的横木。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-轼"},{"id":"glyph-seal-8f7d","script":"seal","character":"载","reading":"zǎi","description":"记载,写在一定的册页里,有郑重的色彩\n⒈年三年五～。\n⒉记在书报刊物上记～。登～。报～。刊～。转～。\n⒈装，乘坐～货。装～。此车可～六人。\n⒉承受～重五吨。\n⒊充满满～而归。风雪～途。\n⒋乃，边，于是～歌～舞。～弛～驱。\n载dài 1.加在头上;用头顶着。 2.尊奉;拥戴。\n载zāi 1.筑墙长版。 2.树立。参见\"载常\"。\n载zī 1.耕作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-载"},{"id":"glyph-seal-8f82","script":"seal","character":"辂","reading":"lù","description":"引申为古代的大车,多指帝王用的\n拉车\n⒈〈古〉车前用来牵引车子的横木。\n⒉〈古〉一种大车玉～。\n辂yà 1.迎上前去。\n辂hé 1.车辕上用来挽车的横木。 2.驾。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辂"},{"id":"glyph-seal-8f84","script":"seal","character":"辄","reading":"zhé","description":"专擅,独断专行,专权\n立即;就\n⒈就，立即，总是动～得咎。所言～听。\n⒉〈古〉专擅，独断专行～行征伐。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辄"},{"id":"glyph-seal-8f85","script":"seal","character":"辅","reading":"fǔ","description":"助手\n面颊\n⒈车轮外的两个直条，用以增强车辐的承载力。〈引〉帮助，协助～助。～导有方。相～相成。\n【辅音】 也叫\"子音\"。发音时，从肺里出来的气，经口腔或鼻腔受到障碍所成的音。拼音字母b、c、d、g等都是辅音。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辅"},{"id":"glyph-seal-8f87","script":"seal","character":"辇","reading":"niǎn","description":"秦汉后特指君后所乘的车\n⒈用人力推拉着走的车子。秦汉以后专指帝王的车子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辇"},{"id":"glyph-seal-8f88","script":"seal","character":"辈","reading":"bèi","description":"也指车列,车队\n世;辈分\n某类人\n群,队\n①行辈；辈分老一～。\n③一世；一生一～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辈"},{"id":"glyph-seal-8f8a","script":"seal","character":"辊","reading":"gǔn","description":"车毂匀整齐一\n滚筒\n滚滚向前流动或运动;像车轮般很快地转动\n运行,运转\n犹混。形容苟且地生活\n⒈机器上能滚动的圆筒形机件～轴。皮～。\n⒉像车轮样飞快的转动～动。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辊"},{"id":"glyph-seal-8f8d","script":"seal","character":"辍","reading":"chuò","description":"放下,舍弃\n撤销;撤除\n取出,拿出\n辍 chuò中止；停止～学、终日不～。\n【辍学】中途停止上学。\n辍chuò停止，废止～学。～止。日夜不～。中途不能～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辍"},{"id":"glyph-seal-8f8e","script":"seal","character":"辎","reading":"zī","description":"①军用器械、粮草、营帐、服装等的总称。\n②外出时所携带的衣服箱笼等。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辎"},{"id":"glyph-seal-8f90","script":"seal","character":"辐","reading":"fú","description":"聚集如辐\n⒈车轮上一条一条的直条，从轮边连结到轮的中心。\n【辐射】光、热、电波等向四周发散的现象。\n【辐辏】\n【辐凑】车辐会聚于车轮的中心。〈喻〉人或物的聚集四方～辏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辐"},{"id":"glyph-seal-8f91","script":"seal","character":"辑","reading":"jí","description":"整套书籍、资料等按内容或发表先后次序分成的各个部分\n聚集\n敛,拖着不使脱落\n把各种来源的书面材料或项目经加工汇编成一个文件或\n⒈〈古〉车厢。泛指车子。\n⒉聚集甲～而兵聚。特指编书报等或编成的书编～。丛书第四～。\n⒊和睦～睦。〈引〉安抚，安定以～一方。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辑"},{"id":"glyph-seal-8f93","script":"seal","character":"输","reading":"shū","description":"交出;缴纳\n已乃劝输巨室,令\n⒈运送，注入运～。～入。～血。\n⒉送给，捐献～财。捐～。\n⒊负，败～了两盘棋。\n输shù 1.经穴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-输"},{"id":"glyph-seal-8f94","script":"seal","character":"辔","reading":"pèi","description":"借指马\n牵;驾驭\n喻法令\n⒈驾驭牲口用的缰绳鞍～。执～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辔"},{"id":"glyph-seal-8f95","script":"seal","character":"辕","reading":"yuán","description":"古代帝王外出止宿时,于险阻处置车为屏藩,又仰两车使辕对峙如门,称辕门\n⒈车前驾牲口的东西车～子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辕"},{"id":"glyph-seal-8f96","script":"seal","character":"辖","reading":"xiá","description":"侍卫\n管辖\n卡,夹\n⒈车上的部件，用于挡住车轮，不使脱落车～。\n⒉管理统～。直～市。\n辖hé 1.见\"輵辖\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辖"},{"id":"glyph-seal-8f97","script":"seal","character":"辗","reading":"niǎn；zhan","description":"通碾”。磙压;碾压\n辗转,也作展转”\n转;回转\n①翻来覆去地转动～转反侧。忧心～转。\n②经过许多曲折～转传诵。\n辗niǎn 1.石碾。 2.谓把糙米加工成熟米的碾轧过程。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辗"},{"id":"glyph-seal-8f99","script":"seal","character":"辙","reading":"zhé","description":"车子\n道路\n途径;门路;路数,路子\n比喻错误或教训\n⒈车轮碾压出的痕迹车～。如出一～。〈引〉车行的路线顺～行。莫抢～儿。又〈引〉杂曲、戏曲、歌词等所押的韵这段戏词合～。\n⒉〈方〉办法有～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辙"},{"id":"glyph-seal-8f9b","script":"seal","character":"辛","reading":"xīn","description":"xīn：(1)辣～辣。五～。\n(2)劳苦，艰难～苦。～劳。\n(3)悲伤～酸。\n(4)天干的第八位，用于作顺序第八的代称～亥革命。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辛"},{"id":"glyph-seal-8f9c","script":"seal","character":"辜","reading":"gū","description":"gū：(1)罪无～。～功（罪行）。死有余～。\n(2)负，背～负。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辜"},{"id":"glyph-seal-8f9e","script":"seal","character":"辞","reading":"cí","description":"口供\n①优美的语言；言词～藻、修～。\n②古典文学的一种体裁～赋、楚～。\n④告别；告辞～行。\n⑤辞职。\n⑥辞退解雇。\n⑦躲避；推托推～、不～劳苦。\n【辞呈】向上级请求辞职的呈文。\n文手法，与辞已不相同。\n【辞格】积极修辞的各种格式。如比喻、借代。又称修辞格。\n【辞海】\n①书名。陆费逵等编。1936年中华书局初版。为综合性大型词典。收单字13000多，词语77000条左右，兼有字典和词典性质，通称旧辞海。\n②书名。辞海编辑委员会编。1965年出版未定稿，1979年出版三卷本，1980年出版缩印本。收单字14872个，词目91706条，内容包括成语、典故、人物、著作、历史事件以及\n各学科名词术语等。为常用的语文工具书。通称新辞海。1989年修订后再版。\n【辞令】社交场合应对得体的话语外交～、善于～。又作词令。\n【辞书】字典、辞典、百科全书、专科辞典的统称。\n【辞源】\n①书名。陆尔奎等1908年编纂。1915年商务印书馆出版，为中国现代第一部综合性辞典，通称旧辞源。\n②书名。1979年出版。主要作为阅读古籍用的工具书和古典文史研究工作者的参考书。全书共收单字12890个，词语84134条，收词范围一般到鸦片战争为止。内容以旧有辞书","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辞"},{"id":"glyph-seal-8f9f","script":"seal","character":"辟","reading":"pì；bì","description":"bì：(1)君主复～。\n(2)指君主招来，授予官职～召。～引。～书。～除（征召推举授官）。～举。\n(3)古同避”，躲，设法躲开。\n(4)古同睥”，睥睨。\n（①～③陃）\npì：(1)开发建设开～。\n(2)驳斥，排除～邪。～谣。～蠹。\n(3)透彻精～。透～。鞭～入里。\n(4)法，刑大～（古代指死刑）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辟"},{"id":"glyph-seal-8fa8","script":"seal","character":"辨","reading":"biàn","description":"biàn：(1)分别，分析，明察～别。～认。～析。～正。～识。明～是非。\n(2)古代土地面积单位，九夫为一辨，七辨为一并。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辨"},{"id":"glyph-seal-8fa9","script":"seal","character":"辩","reading":"biàn","description":"分别,辨别。通辨”\n辩 biàn辩解；争论争～。\n【辩白】说明事实或理由，用来消除误会或受到的指责。又作辨白。\n【辩驳】提出理由或根据来驳斥和否定对方的意见无可～。\n【辩才】辩论的才干。\n【辩护】在刑事诉讼中，被告人及其辩护人，针对控告所进行的申辩话动。\n【辩护人】在刑事案件中，受被告人委托或由法院指定，在法庭上为被告申辩的人。他能向法院提供证明被告人无罪、罪轻的材料和提出减轻、免除其刑事责任的意见。我\n国刑事诉讼法规定，能充当辩护人的有律师、人民团体或被告人所在单位推荐的，或经人民法院许可的公民、被告人的近亲属或监护人。\n【辩论】双方用一定的理由来说明自己的见解，否认或修正对方的意见，以便最后得到正确的认识或共同的意见～会。\n【辩难】辩驳或用难以回答的问题质问对方互相～。\n【辩诬】对错误的指责进行辩解。\n【辩正】辩明是非，纠正错误。又作辨证。\n【辩证】\n①分析考证。又作辨证。\n②合乎辩证法的～的统一。\n【辩证法】\n①关于事物矛盾的运动、发展和变化的一般规律的哲学学说。它是和形而上学相对立的世界观和方法论。认为事物处在不断运动、变化和发展之中，是由于事物内部的矛盾斗争\n所引起的。\n②特指唯物辩证法。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辩"},{"id":"glyph-seal-8fab","script":"seal","character":"辫","reading":"biàn","description":"交织,编结。也作编”\n发辫。分股编紧的头发\n像辫子一样的条状物\n①辫子。把头发分股交叉编成的条条梳小～。\n②指像辫子的东西蒜～子。\n【辫子军】对张勋所属军队的通称。武昌起义后，江南提督张勋率部继续效忠清王朝，禁止部下剪辫子，被称为'辫子军'。在张勋率领下，于1917年6月进驻北京，企图复辟帝\n制。在全国人民强烈的反对下，复辟闹剧仅仅10天便告失败。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辫"},{"id":"glyph-seal-8fb0","script":"seal","character":"辰","reading":"chén","description":"chén：(1)地支的第五位，属龙。\n(2)用于记时～时（上午七点至九点）。\n(3)时日～光。时～。诞～。\n(4)日、月、星的总称北～（北极星）。星～。\n(5)古同晨”，清早。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辰"},{"id":"glyph-seal-8fb1","script":"seal","character":"辱","reading":"rǔ","description":"rǔ：(1)羞耻羞～。耻～。\n(2)使受到羞耻～骂。侮～。折～。\n(3)谦辞，表示承蒙～承。～赐。\n(4)玷污，辜负～没（mò）。～命。玷～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辱"},{"id":"glyph-seal-8fb9","script":"seal","character":"边","reading":"biān","description":"边境\n①物体周围的部分海～。\n②界限～界、～防。\n③表示地位、方向东～、上～。\n④两个'边'连用，表示动作同时进行～学～用。\n⑤几何图形上夹成角的射线或围成多角形的线段。\n⑥姓。\n【边鄙】边远的地方。\n【边币】中国抗日战争时期，陕甘宁边区银行、晋察冀边区银行、豫鄂边区建设银行等发行的货币。\n【边边边定理】有3边对应相等的两个三角形全等，简写为边边边或sss。\n【边陲】边境；边疆西北～。\n【边关】边境上的关口。\n【边角边定理】两个三角形的两组对应边和它们的夹角对应相等，那么两个三角形全等，简写成边角边或sas。\n【边款】刻于印侧的题记。包括年、月，名款、诗文、图案等。\n【边塞】边境的要塞。\n【边饰纹样】装饰于器物边缘的纹样。在服装、书籍封面和商品包装上常应用这种装饰。又称边缘纹样。民间称花边。\n【边心距】正多边形的中心到它的一边的距离叫做正多边形的边心距。正多边形的边心距等于正多边形的内切圆半径r。\n【边缘海】位于大陆的边缘，一侧以大陆为界，另一侧以半岛、岛屿或岛弧与大洋分隔，水流交换通畅。如我国的黄海、东海、南海。又称陆缘海。\n【边缘科学】\n①以学科间有关的共同问题为研究对象，运用多学科的理论和方法探讨解决问题的途径以促进科学全面、深入发展的新兴学科。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-边"},{"id":"glyph-seal-8fbd","script":"seal","character":"辽","reading":"liáo","description":"开阔\n久远","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辽"},{"id":"glyph-seal-8fbe","script":"seal","character":"达","reading":"dá","description":"到达；通畅；表达、传达；通晓事理。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-8fc1","script":"seal","character":"迁","reading":"qiān","description":"晋升或调动\n⒈搬移，换地点～移。～徙。～都。～厂。搬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迁"},{"id":"glyph-seal-8fc2","script":"seal","character":"迂","reading":"yū","description":"yū：(1)曲折，绕远～回。～缓（行动迟缓）。\n(2)言行或见解陈旧不合时宜～论。～气。～儒。～阔（不切合实际）。～腐（说话、行事拘泥于陈旧的准则，不适应新时代）。～夫子（迂腐的读书人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迂"},{"id":"glyph-seal-8fc4","script":"seal","character":"迄","reading":"qì","description":"qì：(1)到，至起～。～今。\n(2)始终（用于未”或无”前）～未成功。～无音信。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迄"},{"id":"glyph-seal-8fc5","script":"seal","character":"迅","reading":"xùn","description":"xùn：快～速。～即。～疾。～捷。～猛。～雷不及掩耳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迅"},{"id":"glyph-seal-8fc7","script":"seal","character":"过","reading":"guò","description":"古国名\n姓,过国之后\n⒈经历，经历某个空间、时间、地点～去。经～。走～。度～。～节。～桥。～河。\n⒉进行某种处理～磅。～滤。～目。\n⒊超越，超出某种范围或限度胜～。太～分。莫～火。～于激动。刚刚～期。已～半数。\n⒋转移，传递，交往～户。～电。～从。\n⒌错误～失。～错。知～必改。\n⒍用在动词后面。\n①助词。〈表〉曾经或完毕看见～。去～了。曾用～。吃～了。\n②与\"来\"、\"去\"连用，〈表〉趋向搬～来。走～去。\n①花费太多。\n②辜负。\n过huò 1.车的盛膏器。 2.通\"祸\"。灾祸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-过"},{"id":"glyph-seal-8fc8","script":"seal","character":"迈","reading":"mài","description":"行走;跨步\n超过,跨越\n时光流逝\n⒈行，去长～。\n⒉跨步向前～进。\n⒊超过，超越三王可～。五帝可越。\n⒋老年～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迈"},{"id":"glyph-seal-8fce","script":"seal","character":"迎","reading":"yíng","description":"yíng：(1)接～接。欢～。～宾。～候。\n(2)面对着，冲着～面。～风（ａ．对着风；ｂ．随风）。～刃而解（jiě）。\n(3)揣度别人心意而投其所好逢～。～合。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迎"},{"id":"glyph-seal-8fd0","script":"seal","character":"运","reading":"yùn","description":"搬运;运输\n将运舟而\n⒈转动，移动～转。～行。\n⒉输送，搬送～输。搬～。空～。～。\n⒊使用，应用，谋划～笔。～用。～筹帷幄。\n⒋迷信者所谓\"命中注定的遭遇\"相信～气、命～者愚昧。\n①人工开挖的水道。\n②特指我国的大运河，从北京到杭州，全长1794公里。\n①物理学上指物体位置不断变移的现象。\n②哲学上指物质存在的形式和根本属性。包括宇宙中所发生的一切变化和过程，宇宙中的各种现象都是物质运动的表现形式。\n③锻炼身体，增强体质的活动体育～动。\n④有组织、有计划、有目的的群众性活动五四～动。\n⑤为达到某种目的而进行的钻营奔走到处～动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-运"},{"id":"glyph-seal-8fd1","script":"seal","character":"近","reading":"jìn","description":"jìn：(1)距离短，与远”相对接～。附～。靠～。～路。～景。舍～求远。～在眉睫。～朱者赤，～墨者黑。～水楼台。\n(2)现在以前不久的时间～况。～来。～代。～岁。～闻。～照。～体诗。\n(3)亲密亲～。～亲。～臣。平易～人。\n(4)差别小，差不多接～。相～。\n(5)浅显言～旨远。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-近"},{"id":"glyph-seal-8fd3","script":"seal","character":"迓","reading":"yà","description":"yà：迎接迎～。～之于门。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迓"},{"id":"glyph-seal-8fd4","script":"seal","character":"返","reading":"fǎn","description":"fǎn：回，归往～。～航。～工。～青（某些植物的幼苗移栽或越冬后，由黄转绿并恢复生长）。～销。～修。～还（huán）。流连忘～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-返"},{"id":"glyph-seal-8fd8","script":"seal","character":"还","reading":"hái；huán","description":"hái：仍然，再，又；尚且。huán：返回；归还；恢复原状。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-8fdb","script":"seal","character":"进","reading":"jìn","description":"水陆并进。\n⒈向前，跟\"退\"相对跃～。向前～。勇者不得独～。\n⒉入，到里面去～门。～厂。～中学。\n⒊收入或买入～钱。～衣服。\n⒋向上移动更～一层楼。\n⒌送上，奉呈～献。～酒。～言。～谏。\n⒍推荐，吸取荐～。引～。吸～。\n⒎旧时房院前后的层次，每一个院叫\"一进\"这座房屋是三～院子。\n①向前发展，比原来好他已有很大的～步。\n②适应时代的要求，对社会发展起促进作用的～步思想。\n⒈闭口，不说话～若寒蝉。〈引〉关闭～门。\n⒉因寒冷而哆嗦打寒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-进"},{"id":"glyph-seal-8fdc","script":"seal","character":"远","reading":"yuǎn","description":"⒈空间或时间的距离长，跟\"近\"相对～方。～古。路～。长～。久～。\n⒉不接近，关系疏～亲。疏～。\n远yuàn 1.离开;避开。 2.不亲近;不接近。 3.违背。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-远"},{"id":"glyph-seal-8fdd","script":"seal","character":"违","reading":"wéi","description":"避开\n⒈背，反，不遵守～背。～反。～犯。～法。不～农时。\n⒉离别，不见面久～了。\n⒊〈古〉避开以～其害。\n违huí 1.掉转。 2.返回。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-违"},{"id":"glyph-seal-8fde","script":"seal","character":"连","reading":"lián","description":"姻亲关系\n⒉联合外～友邦。\n⒊带，加上～说带拉。～根拔掉。～他俩总共四人。\n⒌军队编制单位，是\"营\"的下一级，\"排\"的上一级。\n连liǎn 1.艰难。\n连làn 1.见\"连石\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-连"},{"id":"glyph-seal-8fdf","script":"seal","character":"迟","reading":"chí","description":"迟钝;反应慢,不灵敏\n迟疑;犹豫\n寻声暗问弹者谁,琵琶声\n①缓慢行动～缓。\n②比规定或合适的时间靠后推～、～到早退。\n③姓。\n【迟暮】指人的晚年。\n【迟效肥料】所含养分必须经过微生物分解转化才能被植物吸收利用的肥料。其见效迟缓而后效长，适于作基肥。包括大部分有机肥料及溶解度小的无机肥料。\n【迟疑】拿不定主意～不决。\n⒈缓慢～缓。～ ～不走。\n⒉晚～到。～熟。\n⒊不灵敏～钝。\n⒋长久～久而不相及。\n①早晚。\n②或早或晚。\n迟zhì 1.等待。 2.比及，等到。 3.想望，希望。 4.接待，招待。 5.副词。乃。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迟"},{"id":"glyph-seal-8fe2","script":"seal","character":"迢","reading":"tiáo","description":"tiáo：远，高远的样子～远。～递。千里～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迢"},{"id":"glyph-seal-8fe4","script":"seal","character":"迤","reading":"yǐ；yí","description":"yǐ：(1)地势斜着延长。\n(2)延伸，向天安门～东（向东一带）。\n〔～逦〕曲折连绵。\nyí：〔逶～〕见逶”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迤"},{"id":"glyph-seal-8fe5","script":"seal","character":"迥","reading":"jiǒng","description":"jiǒng：远～异（相差很远）。～然（显然，清清楚楚，如～～不同”）。～乎。～殊。～若两人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迥"},{"id":"glyph-seal-8fe9","script":"seal","character":"迩","reading":"ěr","description":"接近\n迩 ěr近遐～闻名。\n【迩来】近来。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迩"},{"id":"glyph-seal-8fea","script":"seal","character":"迪","reading":"dí","description":"dí：(1)开导启～。\n(2)进弗求弗～。\n(3)继承汉～于秦，有因有革。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迪"},{"id":"glyph-seal-8feb","script":"seal","character":"迫","reading":"pò；pǎi","description":"pò：(1)用强力压制，硬逼逼～。～害。压～。强～。胁～。～降（jiàng）。～降（xiáng）。～不得已。\n(2)接近～近。～冬。\n(3)急促急～。～切。～不及待。\n(4)狭窄地势局～。\npǎi：〔～击炮〕一种火炮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迫"},{"id":"glyph-seal-8fed","script":"seal","character":"迭","reading":"dié","description":"dié：(1)交换，轮流交～。更～。～为宾主。～相为用。\n(2)屡次，连着～连。～忙。高潮～起。\n(3)及忙不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迭"},{"id":"glyph-seal-8fee","script":"seal","character":"迮","reading":"zé","description":"zé：(1)逼迫。\n(2)仓猝～～。\n(3)狭窄山道～狭。\n(4)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迮"},{"id":"glyph-seal-8ff0","script":"seal","character":"述","reading":"shù","description":"shù：(1)讲话，陈说，叙～。～评。描～。论～。综～。～职。～而不作。\n(2)修纂著～。\n(3)循，顺行报我不～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-述"},{"id":"glyph-seal-8ff7","script":"seal","character":"迷","reading":"mí","description":"mí：(1)分辨不清，失去了辨别、判断的能力～信。～糊。～津。～惘。～蒙（ａ．昏暗看不清；ｂ．神志凝不清；ｅ．使迷惑，受蒙蔽）。执～不悟。\n(2)醉心于某种事物，发生特殊的爱好～恋。入～。\n(3)沉醉于某种事物的人棋～。革新～。\n(4)使人陶醉景色～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迷"},{"id":"glyph-seal-8ff8","script":"seal","character":"迸","reading":"bèng","description":"bèng：爆开，溅射～跳。～发。～溅。～裂。～射。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迸"},{"id":"glyph-seal-8ff9","script":"seal","character":"迹","reading":"jì","description":"jì：(1)脚印踪～。足～。血～。笔～。\n(2)物体遗留下的印痕印～。\n(3)前人遗留下的事物古～。实～。\n(4)追寻踪迹汉求将军急，～且至臣家”。\n(5)据实迹考知～汉功臣，亦皆割符世爵”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迹"},{"id":"glyph-seal-8ffd","script":"seal","character":"追","reading":"zhuī；duī","description":"zhuī：(1)赶，紧跟着～逐。～逼。～随。～光。～剿。～捕。～奔逐北。\n(2)回溯过去，补做过去的事～溯。～悼。～加。～认。\n(3)竭力探求，寻求～问。～寻。～究。～索。\n逃；\nduī：(1)雕琢～琢（雕刻）。\n(2)古代乐器钟上用以悬挂的钮眼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-追"},{"id":"glyph-seal-9000","script":"seal","character":"退","reading":"tuì","description":"tuì：(1)向后移动，与进”相对～步。～路。～却。～让。倒～。\n(2)离开，辞去～席。～伍。～职。～休。引～。\n(3)送还，不接受，撤销～还。\n(4)脱落～色。～毛。减～。\n(5)和柔的样子～然。\n(6)迟缓，畏缩求也～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-退"},{"id":"glyph-seal-9001","script":"seal","character":"送","reading":"sòng","description":"sòng：(1)把东西从甲地运到乙地～信。～审。输～。护～。呈～。\n(2)赠给～礼。赠～。雪中～炭。\n(3)陪伴人到某一地点欢～。～别。～亲。\n(4)丢掉断～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-送"},{"id":"glyph-seal-9002","script":"seal","character":"适","reading":"shì","description":"⒈相合，妥当，切合～合。～宜。～当。～龄。～度。～中。正好～用。\n⒉恰好，正巧～得其反。～逢其会。～销对路。\n⒊才，刚才～从何地来？\n⒋舒服她身体不～。\n⒌往，去～长沙。无所～从。\n⒍旧称女子嫁人～人。\n⒈〈古〉疾速。多见于人名。\n适dí 1.专主，作主。 2.同\"嫡\"。正妻称\"嫡妻\"，正妻所生之子称\"嫡子\"。 3.指正统，正宗。 4.亲厚。 5.通\"谛\"。注意，仔细。 6.通\"的\"。指的，对象。 7.通\"\n的\"。清楚，分明。\n适tì 1.见\"适适\"。\n适zhé 1.责备，谴责。 2.责罚，惩罚。 3.贬谪。 4.毛病;过失。 5.旧指天象变异。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-适"},{"id":"glyph-seal-9003","script":"seal","character":"逃","reading":"táo","description":"táo：(1)为躲避不利于自己的环境或事物而离开～跑。～敌。～匿。～遁。～逸。\n(2)躲开不愿意或不敢接触的事物～避。～难（nàn）。～汇。～税。～世（避世）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逃"},{"id":"glyph-seal-9005","script":"seal","character":"逅","reading":"hòu","description":"hòu：〔邂～〕见邂”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逅"},{"id":"glyph-seal-9006","script":"seal","character":"逆","reading":"nì","description":"nì：(1)方向相反，与顺”相对～流。～行。～风。～转（zhuǎn）（局势恶化）。莫～之交。\n(2)抵触，不顺从忤～。忠言～耳。\n(3)背叛，背叛者或背叛者的叛～。～产。\n(4)迎接～旅（旅店）。\n(5)预先～料（预料）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逆"},{"id":"glyph-seal-9009","script":"seal","character":"选","reading":"xuǎn","description":"假借为柬”。挑选,选择\n⒈择，挑拣～择。～派。挑～。\n⒉被选中了的人～。入～。已～上。\n⒊被选出汇编成册的作品～集。诗～。民歌～。\n①〈古〉通过推举或科举盐官吏的制度。\n选suàn 1.数词。万。 2.一说十秭为选。 3.通\"算\"。数;计算。\n选shuā 1.古钱币单位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-选"},{"id":"glyph-seal-900a","script":"seal","character":"逊","reading":"xùn","description":"辞让;退让\n不如,比不上\n⒈让，退让唐尧～位。\n⒉谦让，恭顺谦～。傲慢不～。\n⒊逃远～。～于外。\n⒋差，次～色。略～一筹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逊"},{"id":"glyph-seal-900b","script":"seal","character":"逋","reading":"bū","description":"bū：(1)逃亡～逃。～迁。～荡。\n(2)拖欠～负。～租。～债。\n(3)拖延～留（逗留）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逋"},{"id":"glyph-seal-900d","script":"seal","character":"逍","reading":"xiāo","description":"xiāo：〔～遥〕自由自在，无拘无束，如～～自在”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逍"},{"id":"glyph-seal-900f","script":"seal","character":"透","reading":"tòu","description":"tòu：(1)通过，穿通～明。～镜。～视。～析。渗～。穿～。\n(2)通达～彻。～辟。\n(3)泄露～露。\n(4)极度恨～了。\n(5)显露这朵花白里～红。\n(6)达到饱满、充分的程度雨下～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-透"},{"id":"glyph-seal-9010","script":"seal","character":"逐","reading":"zhú","description":"zhú：(1)强迫离开～客令。放～。驱～。\n(2)依照先后次序，一一挨着～步。～个。～渐。～年。～一。\n(3)追赶～鹿（喻争夺天下）。角（jué）～（争相取胜）。追～。笑～颜开。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逐"},{"id":"glyph-seal-9011","script":"seal","character":"逑","reading":"qiú","description":"qiú：(1)配偶窈窕淑女，君子好～”。\n(2)聚合。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逑"},{"id":"glyph-seal-9012","script":"seal","character":"递","reading":"dì","description":"传;传送\n①传送；传递；投～、～眼色。\n②顺次～补、～增。\n【递补】顺次补充。\n【递减】一次比一次减少。\n【递减数列】从第二项起，每一项都小于它的前面一项的数列。称递减数列。如1，1/2，1/3，…，1/n，…。其中，n是自然数。\n【递进复句】由两个有递进关系的分句组成的句子，后一分句表示的意思比前一分句更进一层。如'他不但会干，而且干得很好'。\n【递进句群】表示递进关系的句群。它与递进复句相同的是都表示递进关系，而不同的是它的前一分句或后一分句不是单句，而是由一组单句紧密结合起来表达一个中心意思的\n句群。\n【递推公式】通过初始的条件，可以初步推出所需要的结论的公式。\n【递增数列】从第二项起，每一项都大于它的前面一项的数列。如1，2，3，…，n，…。又称上升数列。\n【递质】〈医〉指神经末梢兴奋时释放的某种特殊化学物质。它可以使效应器官发生反应，如腺体分泌，也可以使突触后神经原兴奋或抑制。如乙酰胆碱。又称介质。\n递shì 1.通\"适\"。适宜。 2.通\"逝\"。往;去。\n递dài 1.围绕。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-递"},{"id":"glyph-seal-9016","script":"seal","character":"逖","reading":"tì","description":"tì：远～矣！西土之人”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逖"},{"id":"glyph-seal-9017","script":"seal","character":"逗","reading":"dòu","description":"dòu：(1)停留～留。～号。\n(2)引，惹弄～哏。～引。～人。～笑儿。\n(3)同读2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逗"},{"id":"glyph-seal-901a","script":"seal","character":"通","reading":"tōng","description":"tōng：(1)设有阻碍，可以穿过，能够达到～风。～天。～气。～宵。～行。～过。～衢。贯～。四～八达。曲径～幽。\n(2)懂得，彻底明了～晓。～彻。～今博古。～情达理。\n(3)传达～令。～讯。～报。～告。～知。～缉。～谍。\n(4)往来交接～敌。～商。～邮。～融。～假（jiǎ）（汉字的通用和假借）。串～。沟～。\n(5)普遍、全～才（指知识广博，具有多种才能的人）。～论。～体。～身。～读。～常。～病。～盘。普～。\n(6)男女不正当的性行为～奸。私～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-通"},{"id":"glyph-seal-901d","script":"seal","character":"逝","reading":"shì","description":"shì：(1)过去，往～去。～川（逝去的流水，喻过去了的岁月或事物）。光阴易～。子在川上曰～者如斯夫！”\n(2)死，多用于对死者的敬意～世。长～。仙～。\n(3)古同誓”，表决心之词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逝"},{"id":"glyph-seal-901e","script":"seal","character":"逞","reading":"chěng","description":"chěng：(1)显示，施展，炫耀，卖弄～能。～强。～凶。～威风。\n(2)意愿实现，称心～志。～吾愿。不～之徒（因私欲得不到满足而为非作歹，捣乱闹事的人）。\n(3)放任～性。骄～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逞"},{"id":"glyph-seal-901f","script":"seal","character":"速","reading":"sù","description":"sù：(1)快～记。～效。～印。～写。～成。飞～。神～。\n(2)速度慢～。超～。加～。风～。\n(3)邀请，招致不～之客。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-速"},{"id":"glyph-seal-9020","script":"seal","character":"造","reading":"zào","description":"zào：(1)制作，做制～。创～。～物。～反。～孽。建～。～表。～册。～价。～型。粗制滥～。\n(2)瞎编胡编乱～。捏～。\n(3)成就～诣。\n(4)培养～就。\n(5)相对两方面的人，法院里指诉讼的两方。即原告和被告两～。甲～。乙～。\n(6)到，去～访。\n(7)稻子等作物从播种到收割的次数一年两～。晚～。\n(8)时代，年代末～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-造"},{"id":"glyph-seal-9021","script":"seal","character":"逡","reading":"qūn","description":"qūn：退让，退却～巡。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逡"},{"id":"glyph-seal-9022","script":"seal","character":"逢","reading":"féng","description":"féng：(1)遇到～遇。久别重～。～凶化吉。狭路相～。\n(2)迎合，巴结～迎。～君之恶。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逢"},{"id":"glyph-seal-9026","script":"seal","character":"逦","reading":"lǐ","description":"逦迤","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逦"},{"id":"glyph-seal-902e","script":"seal","character":"逮","reading":"dǎi；dài","description":"dài：(1)到，及力有未～。\n(2)捉拿～捕。～系。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逮"},{"id":"glyph-seal-902f","script":"seal","character":"逯","reading":"lù","description":"lù：(1)任意地行走。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逯"},{"id":"glyph-seal-9035","script":"seal","character":"逵","reading":"kuí","description":"kuí：通各方的道路。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逵"},{"id":"glyph-seal-9036","script":"seal","character":"逶","reading":"wēi","description":"wēi：〔～迤〕形容道路、山脉、河流等弯弯曲曲，延续不绝的样子。亦作逶侈”、逶蛇”、委迤”、委移”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逶"},{"id":"glyph-seal-9038","script":"seal","character":"逸","reading":"yì","description":"yì：(1)跑，逃跑，逃～。奔～。\n(2)散失～散。～史。～事。～闻。\n(3)安闲，安乐安～。～乐（安乐）。以～待劳。闲情～致。\n(4)超过一般超～。～兴（xìng）（超逸豪放的兴致）。～趣。～致。～品（超脱绝俗的艺术品）。～珠（特异的珍珠，喻人的品德）。\n(5)隐遁～士（隐居之士）。～民（ａ．旧时称遁世隐居不做官的人；ｂ．亡国后不在新朝代做官的人，亦作佚民”）。\n(6)放任，不受拘束～荡。飘～。骄奢淫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逸"},{"id":"glyph-seal-903b","script":"seal","character":"逻","reading":"luó","description":"遮拦\n用同捋”\n逻卒;巡行兵\n⒈巡察巡～。\n①思维的规律讲得有理，符合～辑。\n②研究思维的形式和规律的科学，叫逻辑学，也叫\"伦理学\"。\n③有时义同\"规律\"这是什么～辑？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逻"},{"id":"glyph-seal-903c","script":"seal","character":"逼","reading":"bī","description":"bī：(1)强迫，威胁～迫。～促。～命。～使。～问。～租。～债。\n(2)切近～近。～真。～视。～肖（xiào）（很相似）。\n(3)狭窄～仄。～侧。～狭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逼"},{"id":"glyph-seal-903e","script":"seal","character":"逾","reading":"yú","description":"yú：(1)越过，超过～期。～常（超过寻常）。～分（fèn）（过分）。～越。～恒（超过寻常）。\n(2)更加～甚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逾"},{"id":"glyph-seal-9041","script":"seal","character":"遁","reading":"dùn","description":"dùn：(1)逃避，躲闪～去。～辞。～世。～北。\n(2)隐，消失～迹。～隐。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遁"},{"id":"glyph-seal-9042","script":"seal","character":"遂","reading":"suí；suì","description":"suì：(1)顺，如意～心。～愿。\n(2)成功，实现未～。功成名～。\n(3)于是，就服药后头痛～止。\n(4)通达何往而不～”。\n(5)进，荐不能退，不能～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遂"},{"id":"glyph-seal-9044","script":"seal","character":"遄","reading":"chuán","description":"chuán：(1)往来频繁。\n(2)快，迅速～往。～返。～飞。～疾。～归。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遄"},{"id":"glyph-seal-9047","script":"seal","character":"遇","reading":"yù","description":"yù：(1)相逢，会面，碰到～到。～见。～事。奇～。遭～。境～。\n(2)机会机～。际～。知～。\n(3)对待，款待待～。冷～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遇"},{"id":"glyph-seal-904d","script":"seal","character":"遍","reading":"biàn","description":"biàn：(1)全面，到处～历（周游）。～布。～及。～野。普～。\n(2)量词，次，回看了三～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遍"},{"id":"glyph-seal-904f","script":"seal","character":"遏","reading":"è","description":"è：(1)阻止～止。～制。～抑。怒不可～。\n(2)古同害”无～尔躬”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遏"},{"id":"glyph-seal-9050","script":"seal","character":"遐","reading":"xiá","description":"xiá：(1)远～方。～心。～观。～迩（远近）。～举（进行；远扬）。～想。\n(2)长久～龄。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遐"},{"id":"glyph-seal-9051","script":"seal","character":"遑","reading":"huáng","description":"huáng：(1)闲暇不～。未～。\n(2)古同惶”，恐惧。\n〔～～〕匆忙不安定的样子。亦作皇皇”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遑"},{"id":"glyph-seal-9052","script":"seal","character":"遒","reading":"qiú","description":"qiú：(1)雄健有力～劲。～健。～炼（诗文、书画等雄健精炼）。～媚（雄健秀美）。\n(2)迫近岁忽忽而～尽兮，恐余寿之弗将”。\n(3)聚。\n(4)坚固。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遒"},{"id":"glyph-seal-9053","script":"seal","character":"道","reading":"dào","description":"dào：(1)路，方向，途径～路。铁～。志同～合。\n(2)指法则、规律～理。～德。～义。得～多助，失～寡助。\n(3)学术或宗教的思想体系～学。传～。修～。\n(4)方法，办法，技术门～。医～。\n(5)指道家”（中国春秋战国时期的一个学派，主要代表人物是老聃和庄周）\n(6)指道教”（中国主要宗教之一，创立于东汉）～观（guàn）。～士。～姑。～行（háng）（僧道修行的功夫，喻技能和本领）。\n(7)指某些反动迷信组织会～门。一贯～。\n(8)说，讲～白。常言～。能说会～。\n(9)用语言表示情意～喜。～歉。～谢。\n(10)线条铅笔～儿。\n(11)中国历史上行政区域的名称。唐代相当于现在的省，清代和民国初年在省以下设道”。\n(12)某些国家行政区域的名称。\n(13)量词一～大河。两～门。上三～漆。\n(14)计量单位，忽米”的通称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-道"},{"id":"glyph-seal-9057","script":"seal","character":"遗","reading":"yí；wei","description":"给予;馈赠\n送交;交付\n以书遗操。\n⒈给予，赠送施～●～。\n⒈丢失～失。\n⒉漏掉，忽略～漏。～忘。\n⒊丢失的东西道不拾～。\n⒋漏掉的部分补～。纤悉无～。\n⒌抛弃～弃。\n⒍余，留，剩下～风。～留。不～余力。\n⒎特指死者留下的～嘱。～物。\n⒐不自觉地排泄大小便或精液～尿。～精。\n遗suí 1.谦虚，顺从。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遗"},{"id":"glyph-seal-9063","script":"seal","character":"遣","reading":"qiǎn","description":"qiǎn：(1)派，送，打发派～。～送。差（chāi）～。调（diào）～。～返（遣送回到原来的地方）。～散（sàn）。～词（说话、写文章运用词语）。\n(2)排解，发泄～闷。消～。～兴（xìng）。～怀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遣"},{"id":"glyph-seal-9065","script":"seal","character":"遥","reading":"yáo","description":"yáo：远～远。～望。～想。～瞻。～指。～瞩。～相呼应。路～知马力。～测。～感。～控。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遥"},{"id":"glyph-seal-906d","script":"seal","character":"遭","reading":"zāo","description":"zāo：(1)遇见，碰到（多指不幸或不利的事）。～遇。～难（nàn）。～受。～殃。～灾。～扰（婉辞，指受招待）。\n(2)周，圈周～。转了一～。\n(3)次一～生，两～熟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遭"},{"id":"glyph-seal-906e","script":"seal","character":"遮","reading":"zhē","description":"zhē：(1)挡～蔽。～挡。～拦。～阳。～没（mò）。～阴。\n(2)掩盖，掩蔽～丑。～盖。～瞒。～掩。～人耳目。\n(3)古同庶”，众多。\n(4)古同者”，这。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遮"},{"id":"glyph-seal-9074","script":"seal","character":"遴","reading":"lín","description":"lín：谨慎选择～选。～柬（同遴选”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遴"},{"id":"glyph-seal-9075","script":"seal","character":"遵","reading":"zūn","description":"zūn：沿着，依照，按照～守。～照。恪～。～循。～行。～养时晦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遵"},{"id":"glyph-seal-907d","script":"seal","character":"遽","reading":"jù；jv","description":"jù：(1)急，仓猝～尔（突然）。～死。～然。匆～。\n(2)惊惧、慌张～色。惶～。\n(3)古代报信的快马或驿车乘～而至。\n(4)遂，就塘有万穴，塞其一，鱼何～无由出？”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遽"},{"id":"glyph-seal-907f","script":"seal","character":"避","reading":"bì","description":"bì：(1)躲，设法躲开～雨。～暑。～世。～讳。回～。～重就轻。～世绝俗。\n(2)防止～免。～孕。～嫌。～雷针。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-避"},{"id":"glyph-seal-9082","script":"seal","character":"邂","reading":"xiè","description":"xiè：〔～逅〕ａ．不期而会，如～～相逢”；ｂ．一旦，偶然，如～～发露，祸及知亲”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邂"},{"id":"glyph-seal-9083","script":"seal","character":"邃","reading":"suì","description":"suì：深远深～。精～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邃"},{"id":"glyph-seal-9088","script":"seal","character":"邈","reading":"miǎo","description":"miǎo：遥远～远。～～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邈"},{"id":"glyph-seal-908b","script":"seal","character":"邋","reading":"lā","description":"lā：〔～遢〕不利落，不整洁（遢”读轻声）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邋"},{"id":"glyph-seal-9091","script":"seal","character":"邑","reading":"yì","description":"yì：(1)城市，都城城～。都～。\n(2)旧指县～人（同乡的人）。～庠（明清时称县学）。～宰。\n(3)古代诸侯分给大夫的封地采～。\n(4)古同悒”，愁闷不安。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邑"},{"id":"glyph-seal-9093","script":"seal","character":"邓","reading":"dèng","description":"古国名\n在今河南省邓县。公元前678年为楚所灭\n古地名\n春秋蔡地,后属楚。在今河南省郾城县东南\n战国楚地,秦置邓县,是故邓侯国。在今湖北省襄樊市北\n战国魏邑,在今河南省孟县西南\n邓 dèng姓。\n勇抗敌，最后弹尽舰伤，遂驾舰撞击敌舰，不幸中敌鱼雷，与全舰官兵一起壮烈牺牲。\n迎。'文革'中被迫害致死。\n月29日在南京被蒋介石秘密杀害。\n海，后因舟中火起，为倭军所乘，遂战死。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邓"},{"id":"glyph-seal-9095","script":"seal","character":"邕","reading":"yōng","description":"yōng：(1)古同雍”，和睦，和谐。\n(2)古同壅”，堵塞。\n(3)中国广西壮族自治区南宁市的别称。\n〔～江〕水名，在中国广西壮族自治区。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邕"},{"id":"glyph-seal-9097","script":"seal","character":"邗","reading":"hán","description":"hán：〔～江〕地名，在中国江苏省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邗"},{"id":"glyph-seal-9099","script":"seal","character":"邙","reading":"máng","description":"máng：〔北～〕山名，在中国河南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邙"},{"id":"glyph-seal-909b","script":"seal","character":"邛","reading":"qióng","description":"qióng：病，劳匪其止共，维王之～”。\n〔～崃〕ａ．地名，在中国四川省；ｂ．山名，在中国四川省。\n〔～都（dū）〕古地名，在今中国四川省西昌市，亦作筇竹”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邛"},{"id":"glyph-seal-90a2","script":"seal","character":"邢","reading":"xíng","description":"xíng：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邢"},{"id":"glyph-seal-90a3","script":"seal","character":"那","reading":"nà；nǎ；nèi；nā","description":"nà：指较远的时间、地方或事物，与这”相对～里。～个。～样。～些。～时。～么。\n这；\nnǎ：同哪”（一）（中国大陆地区已不用）。\n这；\nnèi：义同（一），那”和一”连读的合音，但指数量时不限于一～个。～五年。\n这；\nnā：姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-那"},{"id":"glyph-seal-90a6","script":"seal","character":"邦","reading":"bāng","description":"bāng：国友～。邻～。～交（国和国之间的正式外交关系）。～国（国家）。～人（本国的人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邦"},{"id":"glyph-seal-90aa","script":"seal","character":"邪","reading":"xié；yá；yé；yú；xú","description":"xié：(1)不正当，不正派～恶（è）。～念。～说。\n(2)中医指引起疾病的环境因素寒～。风～。\n(3)迷信的人指鬼神给予的灾祸中（zhòng）～。\n(4)妖异怪诞～魔。～术。\n(5)古同斜”。\n正；\nyá：古同玡”，琅玡山。\n正；\nyé：古同耶”，疑问词。\n正；\nyú：古同餹”。\n正；\nxú：古同徐”，缓慢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邪"},{"id":"glyph-seal-90ac","script":"seal","character":"邬","reading":"wū","description":"古地名\n春秋郑邑,后入周。在今河南省偃师县西南\n春秋晋地,在今山西省介休县东北","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邬"},{"id":"glyph-seal-90ae","script":"seal","character":"邮","reading":"yóu","description":"传递文书的驿站\n指传送文书的人\n古代井田间\n⒈寄递信件、金钱、物品等的专设机构、人员～局。～递员。\n⒉有关邮务的买～票。收～费。～寄。～购。\n⒊〈古〉通\"尤\"。过错，罪过不知其～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邮"},{"id":"glyph-seal-90af","script":"seal","character":"邯","reading":"hán","description":"hán：〔～郸〕地名，在中国河北省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邯"},{"id":"glyph-seal-90b0","script":"seal","character":"邰","reading":"tái","description":"tái：(1)古地名，在今中国陕西省武功县西南。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邰"},{"id":"glyph-seal-90b1","script":"seal","character":"邱","reading":"qiū","description":"qiū：(1)同丘”①。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邱"},{"id":"glyph-seal-90b3","script":"seal","character":"邳","reading":"pī","description":"pī：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邳"},{"id":"glyph-seal-90b4","script":"seal","character":"邴","reading":"bǐng","description":"bǐng：(1)古地名，在中国今山东省费县。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邴"},{"id":"glyph-seal-90b5","script":"seal","character":"邵","reading":"shào","description":"shào：(1)古地名，在今中国山西省垣曲县。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邵"},{"id":"glyph-seal-90b6","script":"seal","character":"邶","reading":"bèi","description":"bèi：中国周代诸侯国名，在今河南省汤阴县东南。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邶"},{"id":"glyph-seal-90b8","script":"seal","character":"邸","reading":"dǐ","description":"dǐ：(1)高级官员的住所（现多用于外交场合）官～。府～。私～。\n(2)旅舍客～。～店。\n(3)停～车。\n(4)屏风。\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邸"},{"id":"glyph-seal-90b9","script":"seal","character":"邹","reading":"zōu","description":"古国名\n邹敌楚战。\n通驺”\n邹jù 1.颜浊邹，人名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邹"},{"id":"glyph-seal-90ba","script":"seal","character":"邺","reading":"yè","description":"的首都。隋复为邺县,宋废。故址在今河北省监漳县西,河南什阳市北","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邺"},{"id":"glyph-seal-90bb","script":"seal","character":"邻","reading":"lín","description":"周朝地方基层组织的户口单位\n相连接的家户。邻居;邻国\n⒈接近的，住处靠近的人家～近。～国。～居。四～。比～。\n⒉〈古〉一种居民组织。五家为～，五～为里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邻"},{"id":"glyph-seal-90be","script":"seal","character":"邾","reading":"zhū","description":"zhū：古国名，在中国今山东省邹县。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邾"},{"id":"glyph-seal-90c1","script":"seal","character":"郁","reading":"yù","description":"郁夷\n古地名『置县。在今陕西省陇县西\n物实无中核者谓之郁\n郁 〈形〉\n文采美盛\n丰盛\n⒈茂盛，树木丛生葱～。\n⒉忧愁，愁闷忧～。抑～。\n⒊草木腐臭～气。\n⒋形容香气馥～。\n⒌〈古〉通\"燠\"。\n①有文采文采～ ～。\n②忧愁，愁闷～ ～不乐。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郁"},{"id":"glyph-seal-90c4","script":"seal","character":"郄","reading":"qiè；xì","description":"qiè：姓。\nxì：古同鄐”，姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郄"},{"id":"glyph-seal-90c5","script":"seal","character":"郅","reading":"zhì","description":"zhì：(1)最，极～治（治理得极好）。～隆（昌盛）。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郅"},{"id":"glyph-seal-90c7","script":"seal","character":"郇","reading":"xún；huán","description":"xún：(1)中国周代诸侯国名，在今山西省临猗县西南。\n(2)姓。\nhuán：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郇"},{"id":"glyph-seal-90ca","script":"seal","character":"郊","reading":"jiāo","description":"jiāo：城外～区。～外。～游。～野。荒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郊"},{"id":"glyph-seal-90ce","script":"seal","character":"郎","reading":"láng；làng","description":"láng：(1)对年轻男子的称呼大～。～才女貌。\n(2)对某种人的称呼货～。女～。\n(3)旧时妻称夫或情人～君。\n(4)封建时代的官名～中（ａ．古官名；ｂ．中医医生）。侍～。员外～。\n(5)姓。\nlàng：〔屎壳～〕蜣螂”的俗称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郎"},{"id":"glyph-seal-90cf","script":"seal","character":"郏","reading":"jiá","description":"中国古邑名\n中国古地名。周之旧都\n通夹”。夹持","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郏"},{"id":"glyph-seal-90d1","script":"seal","character":"郑","reading":"zhèng","description":"⒈周代诸侯国名。在今河南省新郑一带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郑"},{"id":"glyph-seal-90d3","script":"seal","character":"郓","reading":"yùn","description":"古地名\n春秋鲁有二郓邑一在今山东省沂水县北。公元前616年,季孙行父所筑。鱼莒屡次争夺,称东郓”。一在今山东省郓城县东。公元前588年鲁成公所筑,称西郓”\n郓城","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郓"},{"id":"glyph-seal-90d7","script":"seal","character":"郗","reading":"xī","description":"xī：(1)（古读ｃｈīㄔˉ）\n(2)古地名，在今中国河南省沁阳县。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郗"},{"id":"glyph-seal-90db","script":"seal","character":"郛","reading":"fú","description":"fú：古代城圈外围的大城～郭（外城）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郛"},{"id":"glyph-seal-90dc","script":"seal","character":"郜","reading":"gào","description":"gào：(1)古地名，在今中国山东省成武县东南。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郜"},{"id":"glyph-seal-90dd","script":"seal","character":"郝","reading":"hǎo","description":"hǎo：(1)古地名，在今中国陕西省户县和周至县。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郝"},{"id":"glyph-seal-90e1","script":"seal","character":"郡","reading":"jùn","description":"jùn：古代行政区域，中国秦代以前比县小，从秦代起比县大～县。秦分天下为三十六～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郡"},{"id":"glyph-seal-90e2","script":"seal","character":"郢","reading":"yǐng","description":"yǐng：古代中国楚国的都城，在今湖北省江陵县附近。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郢"},{"id":"glyph-seal-90e4","script":"seal","character":"郤","reading":"xì","description":"古同“隙”，空隙、间隙；也用作姓氏。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-90e6","script":"seal","character":"郦","reading":"lì","description":"郦道元\n郦lí 1.春秋时鲁地名。\n郦zhí 1.古县名。秦置。故地在今河南南阳西北。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郦"},{"id":"glyph-seal-90e7","script":"seal","character":"郧","reading":"yún","description":"古国名\n在今湖北什陆县。春秋时为楚所灭\n古地名\n春秋卫地。故城在今江苏省如皋县\n春秋吴地,在今江苏省如皋县东\n郧yún郧县，在湖北省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郧"},{"id":"glyph-seal-90e8","script":"seal","character":"部","reading":"bù","description":"bù：(1)全体中的一份～分（分”读轻声）。外～。腹～。局～。全～。～件。～位（位置）。\n(2)机关企业按业务范围分设的单位外交～。编辑～。～队（军队）。\n(3)具有统属关系所～五十人。～下。～将。～属。～首。～落（luò）。\n(4)安置安排～署。\n(5)量词一～小说。三～汽车。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-部"},{"id":"glyph-seal-90eb","script":"seal","character":"郫","reading":"pí","description":"pí：〔～县〕地名，在中国四川省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郫"},{"id":"glyph-seal-90ed","script":"seal","character":"郭","reading":"guō","description":"guō：(1)城外围着城的墙城～。爷娘闻女来，出～相扶将”。\n(2)物体的外框或外壳。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郭"},{"id":"glyph-seal-90ef","script":"seal","character":"郯","reading":"tán","description":"tán：〔～城〕地名，在中国山东省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郯"},{"id":"glyph-seal-90f4","script":"seal","character":"郴","reading":"chēn","description":"chēn：〔～州〕地名，在中国湖南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郴"},{"id":"glyph-seal-90f8","script":"seal","character":"郸","reading":"dān","description":"在河北省。郸城”,县名,在河南\n郸dān［郸城］县名，在河南省。\n郸duō 1.汉侯国名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郸"},{"id":"glyph-seal-90fd","script":"seal","character":"都","reading":"dōu；dū","description":"dū：(1)大都市～市。～会。通～大邑。\n(2)一国的最高行政机关所在的地方，京城首～。国～。京～。建～。\n(3)美好雍容闲雅，甚～”。～丽。～雅。\n(4)总～为一集。\n(5)居～卿相之位”。\n(6)古代称头目、首领。\n(7)姓。\n皆；全；\ndōu：(1)全，完全～要。功课学得～不错。\n(2)表示语气的加重一动～不动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-都"},{"id":"glyph-seal-90fe","script":"seal","character":"郾","reading":"yǎn","description":"古地名，今河南省漯河市有郾城区。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-90ff","script":"seal","character":"郿","reading":"méi","description":"郿méi郿县，今作\"眉县\"。在陕西省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郿"},{"id":"glyph-seal-9102","script":"seal","character":"鄂","reading":"è","description":"è：(1)中国湖北省的别称。\n(2)古同谔”，正直的话。\n(3)古同愕”，惊讶。\n(4)古同萼”，花托。\n(5)边界纷被丽而亡～”。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鄂"},{"id":"glyph-seal-9104","script":"seal","character":"鄄","reading":"juàn","description":"juàn：〔～城〕地名，在中国山东省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鄄"},{"id":"glyph-seal-9119","script":"seal","character":"鄙","reading":"bǐ","description":"bǐ：(1)中国周代地方组织单位之一，五百家为一鄙～师（古官名，周制每县五鄙，鄙师”掌其鄙之政令祭祀）。\n(2)郊野之处，边远的地方边～。\n(3)粗俗～陋。～俗。～夫。～近（庸俗浅近）。\n(4)轻蔑，看不起～视。～夷。～弃。～薄。\n(5)品质低劣卑～。\n(6)谦辞，用于自称～人。～老。～见。\n(7)吝啬～吝。～诈（贪吝诈伪）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鄙"},{"id":"glyph-seal-911e","script":"seal","character":"鄞","reading":"yín","description":"yín：〔～县〕地名，在中国浙江省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鄞"},{"id":"glyph-seal-9122","script":"seal","character":"鄢","reading":"yān","description":"yān：(1)中国周代诸侯国名，在今河南省焉陵县一带。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鄢"},{"id":"glyph-seal-912f","script":"seal","character":"鄯","reading":"shàn","description":"shàn：〔～善〕ａ．古代西域国名；ｂ．地名，在中国新疆维吾尔自治区。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鄯"},{"id":"glyph-seal-9131","script":"seal","character":"鄱","reading":"pó","description":"pó：〔～阳湖〕湖名，在中国江西省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鄱"},{"id":"glyph-seal-9143","script":"seal","character":"酃","reading":"líng","description":"líng：〔～县〕地名，在中国湖南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酃"},{"id":"glyph-seal-9146","script":"seal","character":"酆","reading":"fēng","description":"fēng：姓。\n〔～都（dū）城〕迷信传说指阴间。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酆"},{"id":"glyph-seal-9149","script":"seal","character":"酉","reading":"yǒu","description":"yǒu：(1)地支的第十位，属鸡。\n(2)用于计时～时（下午五点至七点）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酉"},{"id":"glyph-seal-914a","script":"seal","character":"酊","reading":"dǐng；dīng","description":"dīng：医药上用酒精和药物配制而成的液剂～剂。碘～。颠茄～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酊"},{"id":"glyph-seal-914b","script":"seal","character":"酋","reading":"qiú","description":"qiú：(1)长官～长。\n(2)（盗匪、侵略者的）首领匪～。敌～。\n(3)酒熟。\n(4)古代对造酒的女奴的称谓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酋"},{"id":"glyph-seal-914c","script":"seal","character":"酌","reading":"zhuó","description":"zhuó：(1)斟酒对～。\n(2)饮酒宴会便～。清～。\n(3)考虑，度量～办。～定。～情。斟～。～加修改。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酌"},{"id":"glyph-seal-914d","script":"seal","character":"配","reading":"pèi","description":"pèi：(1)两性结合～偶。～种（zhǒng）。\n(2)相互分工合作～合。～器。\n(3)用适当的标准加以调和～料。～制。～伍。～药。～色。～餐。\n(4)有计划地分派、安排～备。～置。～给（jǐ）。分～。搭～。\n(5)把缺少的补足～套。～乐（yuè）。装～。\n(6)衬托，陪衬～搭。～角儿（juér）。～殿§花～绿叶。\n(7)够得上～得上。\n(8)古代把罪人遣放到边远地区充军～军。发～。刺～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-配"},{"id":"glyph-seal-9152","script":"seal","character":"酒","reading":"jiǔ","description":"jiǔ：用高粱、米、麦或葡萄等发酵制成的含乙醇的饮料白～。啤～。料～。鸡尾～。茅台～。～浆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酒"},{"id":"glyph-seal-915d","script":"seal","character":"酝","reading":"yùn","description":"逐渐造成\n⒈酿酒春～夏成。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酝"},{"id":"glyph-seal-9162","script":"seal","character":"酢","reading":"zuò","description":"zuò：客人用酒回敬主人酬～（主客相互敬酒，引申为朋友交往应酬）。～爵（回敬主人用的酒器）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酢"},{"id":"glyph-seal-9163","script":"seal","character":"酣","reading":"hān","description":"hān：(1)酒喝得很畅快～饮。半～。～醉。酒～耳热。\n(2)尽量，痛快～畅。～赏（恣意游赏）。～眠。～然。\n(3)浓，盛～春（春色正浓）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酣"},{"id":"glyph-seal-9164","script":"seal","character":"酤","reading":"gū","description":"gū：(1)买酒。\n(2)卖酒。\n(3)清酒，一夜就熟的酒清～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酤"},{"id":"glyph-seal-9169","script":"seal","character":"酩","reading":"mǐng","description":"mǐng：〔～酊（dǐng）〕醉得迷迷糊糊的，如～～大醉”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酩"},{"id":"glyph-seal-916a","script":"seal","character":"酪","reading":"lào","description":"lào：(1)用动物的乳汁做成的半凝固食品奶～。干～。～蛋白（一种含磷的复合蛋白。乳中蛋白质的主要成分。营养价值较高。可制成干酪）。\n(2)用果实做的糊状食品果～。杏仁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酪"}];
